import { afterEach, expect, it } from 'vitest';
// Exercise emitted component CSS as well as the generated attribute API.
// @ts-ignore Production loader is generated by the package build.
import { defineCustomElements } from '../../../../../packages/browser/components/dist/loader';
defineCustomElements();

const update = async () => { await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))); };
afterEach(() => { document.body.innerHTML = ''; });

it('applies canonical orientation to standalone and parent-controlled step geometry', async () => {
  document.body.innerHTML = '<q-step-diagram-item orientation="horizontal" layout="vertical"></q-step-diagram-item><q-step-diagram orientation="horizontal"><q-step-diagram-item></q-step-diagram-item></q-step-diagram>';
  await customElements.whenDefined('q-step-diagram-item');
  await customElements.whenDefined('q-step-diagram');
  await Promise.all(Array.from(document.querySelectorAll('q-step-diagram, q-step-diagram-item')).map(el => (el as any).componentOnReady()));
  await update();
  const items = Array.from(document.querySelectorAll('q-step-diagram-item'));
  for (const item of items) expect(getComputedStyle(item.shadowRoot!.querySelector('.step-item')!).flexDirection).toBe('column');
  document.querySelector('q-step-diagram')!.orientation = 'vertical';
  items[0].orientation = 'vertical';
  await update();
  for (const item of items) expect(getComputedStyle(item.shadowRoot!.querySelector('.step-item')!).flexDirection).toBe('row');
});

it('changes quantity control order and geometry using orientation', async () => {
  document.body.innerHTML = '<q-quantity-selector orientation="vertical" variant="horizontal"></q-quantity-selector>';
  await customElements.whenDefined('q-quantity-selector');
  await document.querySelector('q-quantity-selector')!.componentOnReady();
  await update();
  const el = document.querySelector('q-quantity-selector')!;
  const root = el.shadowRoot!.querySelector('.quantity-selector')!;
  expect(getComputedStyle(root).flexDirection).toBe('column');
  expect(root.firstElementChild!.classList.contains('quantity-btn-increment')).toBe(true);
  el.orientation = 'horizontal';
  await update();
  expect(getComputedStyle(root).flexDirection).toBe('row');
  expect(root.firstElementChild!.classList.contains('quantity-btn-decrement')).toBe(true);
});
